import { useState } from 'react'

const TaskInput = ({ onAddTask }) => {
  const [inputValue, setInputValue] = useState('')
  const inputRef = useRef(null)

  const handleSubmit = (e) => {
    e.preventDefault()
    if (inputValue.trim()) {
      onAddTask(inputValue)
      setInputValue('')
      inputRef.current.focus()
    }
  }

  return (
    <form onSubmit={handleSubmit} className="task-input-form">
      <input
        ref={inputRef}
        type="text"
        placeholder="Add new task..."
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        required
        className="task-input-field"
      />
      <button
type="submit"
        className="task-input-button"
      >Add Task</button>
    </form>
  )
}

export default TaskInput

import { useState } from 'react'

const TaskItem = ({ task, onToggle, onEdit, onDelete }) => {
  const [isEditing, setIsEditing] = useState(false)
  const [editTitle, setEditTitle] = useState(task.title)

  const handleToggle = () => {
    onToggle(task.id)
  }

  const handleEditStart = () => {
    setIsEditing(true)
    setEditTitle(task.title)
  }

  const handleEditSave = (e) => {
    e.preventDefault()
    const newTitle = e.target[0].value.trim()
    if (newTitle) {
      onEdit(task.id, newTitle)
      setIsEditing(false)
    }
  }

  const handleEditCancel = () => {
    setIsEditing(false)
    setEditTitle(task.title)
  }

  return (
    <li
      className={\`task-item \${task.completed ? 'completed' : ''} \${isEditing ? 'editing' : ''}\`}
      style={{ textDecoration: task.completed ? 'line-through' : 'none' }}
    >
      {isEditing ? (
        <form
          onSubmit={handleEditSave}
          className="edit-form"
        >
          <input
            type="text"
            value={editTitle}
            onChange={(e) => setEditTitle(e.target.value)}
            required
            className="edit-input"
          />
          <button
type="submit"
            className="edit-save-button"
          >Save</button>
          <button
type="button"
            onClick={handleEditCancel}
            className="edit-cancel-button"
          >Cancel</button>
        </form>
      ) : (
        <span
          className="task-title"
          onClick={handleEditStart}
          style={{ cursor: 'pointer' }}
        >
          {task.title}
        </span>
      )}
      <div className="task-actions">
        <button
          className="toggle-button"
          onClick={handleToggle}
          style={{ textDecoration: task.completed ? 'line-through' : 'none' }}
        >
          {task.completed ? 'Undo' : 'Complete'}
        </button>
        <button
          className="edit-button"
          onClick={handleEditStart}
          style={{ cursor: 'pointer' }}
        >Edit</button>
        <button
          className="delete-button"
          onClick={() => onDelete(task.id)}
          style={{ cursor: 'pointer' }}
        >Delete</button>
      </div>
    </li>
  )
}

export default TaskItem

import { useState } from 'react'
import TaskItem from './TaskItem'

const TaskList = ({ tasks, onToggle, onEdit, onDelete }) => {
  return (
    <ul className="task-list" style={{ listStyle: 'none', padding: 0 }}>
      {tasks.map((task) => (
        <TaskItem
          key={task.id}
          task={task}
          onToggle={onToggle}
          onEdit={onEdit}
          onDelete={onDelete}
        />
      ))}
    </ul>
  )
}

export default TaskList

import { useState } from 'react'

const TaskFilter = ({ filter, onFilterChange }) => {
  return (
    <div className="task-filter" style={{ display: 'flex', gap: '10px', marginTop: '15px' }}>
      <button
        className={\`filter-button \${filter === 'all' ? 'active' : ''}`}
        onClick={() => onFilterChange('all')}
        style={{ padding: '8px 16px', border: '1px solid #ccc', borderRadius: '4px', background: filter === 'all' ? '#e0e0e0' : 'white', cursor: 'pointer' }}
      >
        All
      </button>
      <button
        className={\`filter-button \${filter === 'active' ? 'active' : ''}`}
        onClick={() => onFilterChange('active')}
        style={{ padding: '8px 16px', border: '1px solid #ccc', borderRadius: '4px', background: filter === 'active' ? '#e0e0e0' : 'white', cursor: 'pointer' }}
      >
        Active
      </button>
      <button
        className={\`filter-button \${filter === 'completed' ? 'active' : ''}`}
        onClick={() => onFilterChange('completed')}
        style={{ padding: '8px 16px', border: '1px solid #ccc', borderRadius: '4px', background: filter === 'completed' ? '#e0e0e0' : 'white', cursor: 'pointer' }}
      >
        Completed
      </button>
    </div>
  )
}

export default TaskFilter

import { useState } from 'react'
import TaskInput from './components/TaskInput'
import TaskList from './components/TaskList'
import TaskFilter from './components/TaskFilter'

const App = () => {
  const [tasks, setTasks] = useState([])
  const [filter, setFilter] = useState('all')

  const addTask = (title) => {
    setTasks((prev) => [...prev, { id: Date.now(), title, completed: false }])
  }

  const toggleTask = (id) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === id ? { ...task, completed: !task.completed } : task
      )
    )
  }

  const editTask = (id, newTitle) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === id ? { ...task, title: newTitle } : task
      )
    )
  }

  const deleteTask = (id) => {
    setTasks((prev) => prev.filter((task) => task.id !== id))
  }

  const filteredTasks = () => {
    if (filter === 'all') return tasks
    if (filter === 'active') return tasks.filter((t) => !t.completed)
    if (filter === 'completed') return tasks.filter((t) => t.completed)
    return tasks
  }

  const handleFilterChange = (newFilter) => {
    setFilter(newFilter)
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px' }}>
      <h1 style={{ textAlign: 'center', marginBottom: '20px' }}>Task Manager</h1>
      <TaskInput onAddTask={addTask} />
      <TaskList
        tasks={filteredTasks()}
        onToggle={toggleTask}
        onEdit={editTask}
        onDelete={deleteTask}
      />
      <TaskFilter filter={filter} onFilterChange={handleFilterChange} />
    </div>
  )
}

export default App

