import { render, screen } from '@testing-library/react'
import App from '../App'

test('can add a new task', () => {
  render(<App />)
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'Test task'
  fireEvent.change(input)
  fireEvent.click(addButton)
  expect(screen.getByText('Test task')).toBeInTheDocument()
})

test('can edit a task title', () => {
  render(<App />)
  // Add a task first
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'Edit me'
  fireEvent.change(input)
  fireEvent.click(addButton)
  // Click on task title to enter edit mode
  const taskTitle = screen.getByText('Edit me')
  fireEvent.click(taskTitle)
  const editInput = screen.getByRole('textbox', { name: /old title/i })
  expect(editInput).toBeInTheDocument()
})

test('can mark task as completed', () => {
  render(<App />)
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'Complete me'
  fireEvent.change(input)
  fireEvent.click(addButton)
  const toggleButton = screen.getByText('Complete')
  fireEvent.click(toggleButton)
  expect(screen.getByText('Complete me')).toHaveStyle({ textDecoration: 'line-through' })
})

test('can delete a task', () => {
  render(<App />)
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'To delete'
  fireEvent.change(input)
  fireEvent.click(addButton)
  const deleteButton = screen.getByText('Delete')
  fireEvent.click(deleteButton)
  expect(screen.getByText('To delete')).not.toBeInTheDocument()
})

test('filters active tasks', () => {
  render(<App />)
  // Add an active task
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'Active task'
  fireEvent.change(input)
  fireEvent.click(addButton)
  // Add a completed task
  input.value = 'Completed task'
  fireEvent.change(input)
  fireEvent.click(addButton)
  // Mark first task as completed
  const toggleButton = screen.getByText('Complete')
  fireEvent.click(toggleButton)
  // Filter to active
  const filterButtons = screen.getAllByRole('button', { name: /all|active|completed/i })
  filterButtons[1].click() // Active
  expect(screen.getAllByText('Active task')).toHaveLength(1)
  expect(screen.getAllByText('Completed task')).not.toBeInTheDocument()
})

test('filters completed tasks', () => {
  render(<App />)
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'Completed task'
  fireEvent.change(input)
  fireEvent.click(addButton)
  const toggleButton = screen.getByText('Complete')
  fireEvent.click(toggleButton)
  // Filter to completed
  const filterButtons = screen.getAllByRole('button', { name: /all|active|completed/i })
  filterButtons[2].click() // Completed
  expect(screen.getAllByText('Completed task')).toHaveLength(1)
})

test('filters all tasks', () => {
  render(<App />)
  const input = screen.getByRole('textbox', { name: /add new task/i })
  const addButton = screen.getByRole('button', { name: /add task/i })
  input.value = 'Task 1'
  fireEvent.change(input)
  fireEvent.click(addButton)
  input.value = 'Task 2'
  fireEvent.change(input)
  fireEvent.click(addButton)
  // Filter to all
  const filterButtons = screen.getAllByRole('button', { name: /all|active|completed/i })
  filterButtons[0].click() // All
  expect(screen.getAllByText('Task 1')).toBeInTheDocument()
  expect(screen.getAllByText('Task 2')).toBeInTheDocument()
})
